import { chromium } from 'playwright'

const BASE = process.env.BASE || 'http://127.0.0.1:8092'

const browser = await chromium.launch()
const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 } })
const page = await ctx.newPage()

// Intercept the records API and make it hang (never resolve) to simulate backend unreachable
await page.route('**/portal/public/broker/records**', async (route) => {
  // hold forever
  await new Promise(() => {})
})

const logs = []
page.on('console', (m) => logs.push(`[${m.type()}] ${m.text()}`))

await page.goto(`${BASE}/#/UnifiedLogin?portal=brokers`, { waitUntil: 'domcontentloaded' })
await page.waitForTimeout(1500)

// The broker list: agency tab is default kind? We need to open an agency detail.
// Try clicking first row in the table.
const d2 = await page.evaluate(() => document.body.innerText.slice(0, 400))
console.log('INITIAL TEXT:', JSON.stringify(d2))

// Try to find a clickable row / link to open detail
const rowInfo = await page.evaluate(() => {
  const rows = Array.from(document.querySelectorAll('.portal-table tbody tr'))
  return rows.slice(0, 5).map((r) => r.innerText.replace(/\s+/g, ' ').trim())
})
console.log('ROWS:', JSON.stringify(rowInfo))

// Click the first data row to open detail
let clicked = false
const rows = page.locator('.portal-table tbody tr')
const cnt = await rows.count()
for (let i = 0; i < cnt; i++) {
  try {
    await rows.nth(i).click({ timeout: 2000 })
    clicked = true
    break
  } catch {}
}
console.log('CLICKED:', clicked)
await page.waitForTimeout(200)

// Observe the transaction loading skeleton presence over time
const sample = async (label) => {
  const st = await page.evaluate(() => {
    const loadRow = document.querySelector('.portal-table-loading')
    const sBars = document.querySelectorAll('.portal-skeleton-bar').length
    const txt = document.body.innerText
    const hasEmpty = txt.includes('暂无数据')
    return { loadingRow: !!loadRow, sBars, hasEmpty }
  })
  console.log(`T=${label}:`, JSON.stringify(st))
  return st
}

await sample('0ms')
for (const t of [1000, 2000, 3000, 3500, 4500]) {
  await page.waitForTimeout(t === 1000 ? 1000 : 500)
  await sample(`${t}ms`)
}

await page.screenshot({ path: 'verify-broker-skeleton.png', fullPage: false })
console.log('CONSOLE:', logs.slice(0, 20).join('\n'))
await browser.close()

