import { chromium } from 'playwright'
const BASE = process.env.BASE || 'http://127.0.0.1:8092'
const browser = await chromium.launch()
const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 } })
const page = await ctx.newPage()

// hang records API
await page.route('**/portal/public/broker/records**', async () => { await new Promise(() => {}) })

await page.goto(`${BASE}/#/UnifiedLogin?portal=brokers`, { waitUntil: 'domcontentloaded' })
await page.waitForTimeout(1500)

// dump what nav/menu links exist to reach 经纪机构信息
const menu = await page.evaluate(() => {
  const links = Array.from(document.querySelectorAll('a,button,[role=menuitem],.nav-item,.menu-item,span'))
    .map(e => e.innerText && e.innerText.trim())
    .filter(t => t && (t.includes('经纪机构') || t.includes('从业人员') || t.includes('信用信息')))
  return [...new Set(links)]
})
console.log('MENU MATCHES:', JSON.stringify(menu))

// Try clicking '经纪机构信息'
async function tryClick(text) {
  const el = page.getByText(text, { exact: false }).first()
  try { await el.click({ timeout: 2500 }); return true } catch(e){ return false }
}
const c1 = await tryClick('经纪机构信息')
console.log('clicked 经纪机构信息:', c1)
await page.waitForTimeout(1200)

// snapshot
const state = await page.evaluate(() => ({
  url: location.hash,
  breadcrumb: document.querySelector('.portal-breadcrumb')?.innerText?.replace(/\s+/g,' ').trim(),
  hasAgencyDetail: !!document.querySelector('.broker-transactions-agency-detail, .broker-profile'),
  tableRows: document.querySelectorAll('.portal-table tbody tr').length,
  loadingRow: !!document.querySelector('.portal-table-loading'),
  emptyText: document.body.innerText.includes('暂无数据'),
  text: document.body.innerText.slice(0,200)
}))
console.log('AFTER NAV:', JSON.stringify(state))

// Click a 基本信息 link to open detail
const basic = page.getByText('基本信息', { exact: true }).first()
let cb=false
try { await basic.click({ timeout: 2500 }); cb=true }catch(e){}
console.log('clicked 基本信息:', cb)

const sample = async (label) => {
  const st = await page.evaluate(() => {
    const loadRow = document.querySelector('.portal-table-loading')
    const sBars = document.querySelectorAll('.portal-skeleton-bar').length
    const txt = document.body.innerText
    return { loadingRow: !!loadRow, sBars, hasEmpty: txt.includes('暂无数据'), hash: location.hash }
  })
  console.log(`T=${label}:`, JSON.stringify(st)); return st
}
await sample('0')
for (const t of [500,1000,1500,2000,2500,3000,3500,4000,5000]) {
  await page.waitForTimeout(500); await sample(`${t}`)
}
await page.screenshot({ path: 'verify-broker-skeleton2.png', fullPage: false })
await browser.close()

