// List clickable nav entries
const navs = await page.evaluate(() => {
  return Array.from(document.querySelectorAll('a,button,[class*=nav],[class*=menu],[class*=tab]'))
    .map(e=>({t:(e.innerText||'').replace(/\s+/g,' ').trim(), c:e.className}))
    .filter(x=>x.t).slice(0,40)
})
console.log('NAVS:', JSON.stringify(navs, null, 0))
await browser.close()

