import { chromium } from 'playwright'
const BASE = process.env.BASE || 'http://127.0.0.1:8092'
const browser = await chromium.launch()
const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 } })
const page = await ctx.newPage()

// hang the records API
await page.route('**/portal/public/broker/records**', async () => { await new Promise(() => {}) })

await page.goto(`${BASE}/#/UnifiedLogin?portal=brokers`, { waitUntil: 'domcontentloaded' })
await page.waitForTimeout(1500)

// Find BrokerPages Vue component instance
const found = await page.evaluate(() => {
  const root = document.querySelector('.public-portal-screen')
  if (!root) return 'no-root'
  const walk = (vm) => {
    if (vm.$options && vm.$options.name === 'BrokerPages') return vm
    for (const c of vm.$children) { const r = walk(c); if (r) return r }
    return null
  }
  // root may itself be the public-portal-screen component; climb to vue root
  let top = root.__vue__
  while (top && top.$parent) top = top.$parent
  const bp = walk(top)
  if (!bp) return 'no-BrokerPages'
  // force agency-detail with a resolved owner id
  bp.profileType = 'agency-detail'
  bp.detailData = { companyRecordId: 'TEST', companyId: 'TEST', name: '测试机构' }
  bp.showCreditRecords = false
  bp.transactionLoading = false
  window.__bp = bp
  return 'ok'
})
console.log('FIND:', found)
if (found !== 'ok') { await browser.close(); process.exit(1) }

// trigger loadTransactionsIfNeeded (records will hang)
await page.evaluate(() => { window.__bp.loadTransactionsIfNeeded() })

const sample = async (label) => {
  const s = await page.evaluate(() => ({
    transactionLoading: window.__bp.transactionLoading,
    txCount: (window.__bp.transactions||[]).length,
    skeletonBarsVisible: document.querySelectorAll('.portal-skeleton-bar').length,
    loadingRow: !!document.querySelector('.portal-table-loading'),
  }))
  console.log(`T=${label}:`, JSON.stringify(s))
}
for (const t of [0,500,1000,1500,2000,2500,3000,3200,3500,4000]) {
  await sample(t)
  await page.waitForTimeout(500)
}
await browser.close()

